-- Phase 1 foundation schema. Design: docs/database/ENTITY_CATALOG.md, DATABASE_DESIGN.md.
-- Row-level security, grants and triggers are applied in 0002_rls_and_grants.sql.
-- Conventions: UUID primary keys generated by the application (UUIDv7), timestamptz in UTC,
-- text + CHECK instead of native enums, NUMERIC (never float) for any financial value.

CREATE EXTENSION IF NOT EXISTS citext;

-- Database roles (NOLOGIN group roles). Login users are created per environment as members:
--   CREATE ROLE artify_app_login LOGIN PASSWORD '...' IN ROLE artify_app;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'artify_app') THEN
    CREATE ROLE artify_app NOLOGIN NOSUPERUSER NOBYPASSRLS;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'artify_platform') THEN
    CREATE ROLE artify_platform NOLOGIN NOSUPERUSER NOBYPASSRLS;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'artify_dispatcher') THEN
    CREATE ROLE artify_dispatcher NOLOGIN NOSUPERUSER NOBYPASSRLS;
  END IF;
END $$;

CREATE SCHEMA IF NOT EXISTS app;

-- ---------------------------------------------------------------- reference (class R)
CREATE TABLE currencies (
  code        char(3) PRIMARY KEY CHECK (code ~ '^[A-Z]{3}$'),
  name        text NOT NULL,
  minor_unit  smallint NOT NULL CHECK (minor_unit BETWEEN 0 AND 4)
);

CREATE TABLE entitlement_definitions (
  key          text PRIMARY KEY CHECK (key ~ '^(limit|quota|feature)\.[a-z_]+$'),
  scope        text NOT NULL CHECK (scope IN ('organization', 'company')),
  value_type   text NOT NULL CHECK (value_type IN ('int', 'bigint', 'bool')),
  enforcement  text NOT NULL CHECK (enforcement IN ('hard', 'metered', 'flag')),
  unit         text,
  description  text NOT NULL
);

CREATE TABLE permissions (
  key          text PRIMARY KEY CHECK (key ~ '^[a-z_]+(\.[a-z_]+)+$'),
  scope        text NOT NULL CHECK (scope IN ('platform', 'organization', 'company', 'member')),
  description  text NOT NULL
);

-- ---------------------------------------------------------------- platform (class P)
CREATE TABLE subscription_plans (
  id          uuid PRIMARY KEY,
  key         text NOT NULL UNIQUE CHECK (key ~ '^[a-z0-9_]+$'),
  name        text NOT NULL,
  status      text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'retired')),
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE subscription_plan_versions (
  id               uuid PRIMARY KEY,
  plan_id          uuid NOT NULL REFERENCES subscription_plans (id),
  version          integer NOT NULL CHECK (version >= 1),
  billing_interval text NOT NULL DEFAULT 'monthly' CHECK (billing_interval IN ('monthly', 'annual', 'none')),
  price_display    jsonb NOT NULL DEFAULT '{}'::jsonb,   -- display only; billing provider is decision D-2
  effective_from   timestamptz NOT NULL DEFAULT now(),
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (plan_id, version)
);

CREATE TABLE plan_entitlements (
  plan_version_id  uuid NOT NULL REFERENCES subscription_plan_versions (id),
  entitlement_key  text NOT NULL REFERENCES entitlement_definitions (key),
  int_value        bigint CHECK (int_value >= 0),
  bool_value       boolean,
  unlimited        boolean NOT NULL DEFAULT false,
  PRIMARY KEY (plan_version_id, entitlement_key),
  CHECK ( (CASE WHEN int_value IS NOT NULL THEN 1 ELSE 0 END
         + CASE WHEN bool_value IS NOT NULL THEN 1 ELSE 0 END
         + CASE WHEN unlimited THEN 1 ELSE 0 END) = 1 )
);

CREATE TABLE platform_settings (
  key         text PRIMARY KEY,
  value       jsonb NOT NULL,
  updated_at  timestamptz NOT NULL DEFAULT now(),
  updated_by  uuid
);

CREATE TABLE platform_admins (
  id             uuid PRIMARY KEY,
  email          citext NOT NULL UNIQUE,
  display_name   text NOT NULL,
  role_key       text NOT NULL CHECK (role_key IN
                   ('platform_owner', 'platform_admin', 'platform_support', 'platform_billing', 'platform_auditor')),
  password_hash  text NOT NULL,
  status         text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE platform_audit_events (
  id                  uuid NOT NULL,
  created_at          timestamptz NOT NULL DEFAULT now(),
  actor_type          text NOT NULL CHECK (actor_type IN ('platform_admin', 'system')),
  actor_id            uuid,
  action              text NOT NULL,
  target_type         text,
  target_id           text,
  target_organization uuid,
  summary             jsonb NOT NULL DEFAULT '{}'::jsonb,
  ip                  inet,
  user_agent          text,
  correlation_id      text,
  PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);
CREATE TABLE platform_audit_events_default PARTITION OF platform_audit_events DEFAULT;

-- ---------------------------------------------------------------- tenants and identities
CREATE TABLE organizations (
  id                   uuid PRIMARY KEY,
  type                 text NOT NULL CHECK (type IN ('accounting_firm', 'independent_accountant')),
  legal_name           text NOT NULL,
  display_name         text NOT NULL,
  slug                 citext NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'),
  country              char(2) NOT NULL CHECK (country ~ '^[A-Z]{2}$'),
  default_currency     char(3) NOT NULL REFERENCES currencies (code),
  locale               text NOT NULL DEFAULT 'en' CHECK (locale IN ('en', 'ar')),
  ai_processing_policy text NOT NULL DEFAULT 'disabled'
                         CHECK (ai_processing_policy IN ('disabled', 'local_only', 'approved_cloud')),
  status               text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'closed')),
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  row_version          integer NOT NULL DEFAULT 1
);

CREATE TABLE users (
  id                uuid PRIMARY KEY,
  email             citext NOT NULL UNIQUE,
  display_name      text NOT NULL,
  locale            text NOT NULL DEFAULT 'en' CHECK (locale IN ('en', 'ar')),
  status            text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  email_verified_at timestamptz,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE auth_credentials (
  user_id        uuid PRIMARY KEY REFERENCES users (id),
  password_hash  text NOT NULL,
  updated_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE mfa_factors (
  id                uuid PRIMARY KEY,
  user_id           uuid REFERENCES users (id),
  platform_admin_id uuid REFERENCES platform_admins (id),
  type              text NOT NULL DEFAULT 'totp' CHECK (type IN ('totp')),
  secret_encrypted  text NOT NULL,
  confirmed_at      timestamptz,
  last_used_step    bigint,            -- TOTP replay protection: highest accepted 30s time step
  created_at        timestamptz NOT NULL DEFAULT now(),
  CHECK ((user_id IS NULL) <> (platform_admin_id IS NULL))
);
CREATE UNIQUE INDEX mfa_factors_user_totp ON mfa_factors (user_id) WHERE user_id IS NOT NULL;
CREATE UNIQUE INDEX mfa_factors_admin_totp ON mfa_factors (platform_admin_id) WHERE platform_admin_id IS NOT NULL;

CREATE TABLE mfa_recovery_codes (
  id                uuid PRIMARY KEY,
  user_id           uuid REFERENCES users (id),
  platform_admin_id uuid REFERENCES platform_admins (id),
  code_hash         bytea NOT NULL UNIQUE,
  used_at           timestamptz,
  created_at        timestamptz NOT NULL DEFAULT now(),
  CHECK ((user_id IS NULL) <> (platform_admin_id IS NULL))
);

CREATE TABLE devices (
  id               uuid PRIMARY KEY,
  user_id          uuid NOT NULL REFERENCES users (id),
  organization_id  uuid NOT NULL REFERENCES organizations (id),
  platform         text NOT NULL CHECK (platform IN ('windows', 'android', 'ios', 'web')),
  name             text NOT NULL,
  app_version      text,
  key_fingerprint  text,
  status           text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked')),
  last_seen_at     timestamptz,
  created_at       timestamptz NOT NULL DEFAULT now(),
  revoked_at       timestamptz
);
CREATE INDEX devices_org_status ON devices (organization_id, status);

CREATE TABLE sessions (
  id                uuid PRIMARY KEY,
  realm             text NOT NULL CHECK (realm IN ('tenant', 'platform')),
  user_id           uuid REFERENCES users (id),
  platform_admin_id uuid REFERENCES platform_admins (id),
  device_id         uuid REFERENCES devices (id),
  ip                inet,
  user_agent        text,
  mfa_verified_at   timestamptz,
  created_at        timestamptz NOT NULL DEFAULT now(),
  last_used_at      timestamptz NOT NULL DEFAULT now(),
  expires_at        timestamptz NOT NULL,
  revoked_at        timestamptz,
  revoke_reason     text,
  CHECK ((realm = 'tenant' AND user_id IS NOT NULL AND platform_admin_id IS NULL)
      OR (realm = 'platform' AND platform_admin_id IS NOT NULL AND user_id IS NULL))
);
CREATE INDEX sessions_user ON sessions (user_id) WHERE user_id IS NOT NULL;
CREATE INDEX sessions_admin ON sessions (platform_admin_id) WHERE platform_admin_id IS NOT NULL;

CREATE TABLE refresh_tokens (
  id          uuid PRIMARY KEY,
  session_id  uuid NOT NULL REFERENCES sessions (id) ON DELETE CASCADE,
  token_hash  bytea NOT NULL UNIQUE,
  created_at  timestamptz NOT NULL DEFAULT now(),
  expires_at  timestamptz NOT NULL,
  used_at     timestamptz
);
CREATE INDEX refresh_tokens_session ON refresh_tokens (session_id);

CREATE TABLE email_tokens (
  id          uuid PRIMARY KEY,
  user_id     uuid NOT NULL REFERENCES users (id),
  purpose     text NOT NULL CHECK (purpose IN ('verify_email', 'password_reset')),
  token_hash  bytea NOT NULL UNIQUE,
  expires_at  timestamptz NOT NULL,
  used_at     timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE roles (
  id               uuid PRIMARY KEY,
  key              text NOT NULL CHECK (key ~ '^[a-z_]+$'),
  scope            text NOT NULL CHECK (scope IN ('platform', 'organization', 'company')),
  name             text NOT NULL,
  is_system        boolean NOT NULL DEFAULT true,
  organization_id  uuid REFERENCES organizations (id),
  created_at       timestamptz NOT NULL DEFAULT now(),
  CHECK (NOT is_system OR organization_id IS NULL)
);
CREATE UNIQUE INDEX roles_system_key ON roles (key) WHERE organization_id IS NULL;
CREATE UNIQUE INDEX roles_org_key ON roles (organization_id, key) WHERE organization_id IS NOT NULL;

CREATE TABLE role_permissions (
  role_id         uuid NOT NULL REFERENCES roles (id) ON DELETE CASCADE,
  permission_key  text NOT NULL REFERENCES permissions (key),
  PRIMARY KEY (role_id, permission_key)
);

CREATE TABLE organization_memberships (
  id               uuid PRIMARY KEY,
  organization_id  uuid NOT NULL REFERENCES organizations (id),
  user_id          uuid NOT NULL REFERENCES users (id),
  role_id          uuid NOT NULL REFERENCES roles (id),
  status           text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'removed')),
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, user_id)
);
CREATE INDEX org_memberships_user ON organization_memberships (user_id) WHERE status = 'active';

CREATE TABLE companies (
  id                uuid PRIMARY KEY,
  organization_id   uuid NOT NULL REFERENCES organizations (id),
  name              text NOT NULL,
  code              text NOT NULL CHECK (code ~ '^[A-Za-z0-9_-]{1,32}$'),
  tax_registration  text,
  country           char(2) NOT NULL CHECK (country ~ '^[A-Z]{2}$'),
  base_currency     char(3) NOT NULL REFERENCES currencies (code),
  status            text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'archived')),
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  row_version       integer NOT NULL DEFAULT 1,
  UNIQUE (organization_id, id),            -- composite-FK target (ADR-002)
  UNIQUE (organization_id, code)
);

CREATE TABLE company_memberships (
  id               uuid PRIMARY KEY,
  organization_id  uuid NOT NULL,
  company_id       uuid NOT NULL,
  user_id          uuid NOT NULL REFERENCES users (id),
  role_id          uuid NOT NULL REFERENCES roles (id),
  status           text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'removed')),
  created_at       timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (organization_id, company_id) REFERENCES companies (organization_id, id),
  UNIQUE (company_id, user_id)
);
CREATE INDEX company_memberships_user ON company_memberships (user_id) WHERE status = 'active';

CREATE TABLE accountant_assignments (
  id               uuid PRIMARY KEY,
  organization_id  uuid NOT NULL,
  company_id       uuid NOT NULL,
  user_id          uuid NOT NULL REFERENCES users (id),
  assignment_type  text NOT NULL CHECK (assignment_type IN ('primary', 'secondary', 'reviewer')),
  created_at       timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (organization_id, company_id) REFERENCES companies (organization_id, id),
  UNIQUE (company_id, user_id)
);
CREATE INDEX accountant_assignments_user ON accountant_assignments (user_id);

CREATE TABLE invitations (
  id               uuid PRIMARY KEY,
  organization_id  uuid NOT NULL REFERENCES organizations (id),
  email            citext NOT NULL,
  org_role_id      uuid REFERENCES roles (id),
  company_id       uuid,
  company_role_id  uuid REFERENCES roles (id),
  token_hash       bytea NOT NULL UNIQUE,
  invited_by       uuid NOT NULL REFERENCES users (id),
  expires_at       timestamptz NOT NULL,
  accepted_at      timestamptz,
  revoked_at       timestamptz,
  created_at       timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (organization_id, company_id) REFERENCES companies (organization_id, id),
  CHECK ( (org_role_id IS NOT NULL AND company_id IS NULL AND company_role_id IS NULL)
       OR (org_role_id IS NULL AND company_id IS NOT NULL AND company_role_id IS NOT NULL) )
);
CREATE INDEX invitations_org ON invitations (organization_id, email);

-- ---------------------------------------------------------------- subscriptions and entitlements
CREATE TABLE subscriptions (
  id                    uuid PRIMARY KEY,
  organization_id       uuid NOT NULL REFERENCES organizations (id),
  plan_version_id       uuid NOT NULL REFERENCES subscription_plan_versions (id),
  status                text NOT NULL CHECK (status IN ('trialing', 'active', 'past_due', 'suspended', 'cancelled')),
  current_period_start  timestamptz NOT NULL DEFAULT now(),
  current_period_end    timestamptz,
  trial_ends_at         timestamptz,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX subscriptions_one_current ON subscriptions (organization_id)
  WHERE status IN ('trialing', 'active', 'past_due', 'suspended');

CREATE TABLE entitlement_overrides (
  id               uuid PRIMARY KEY,
  organization_id  uuid NOT NULL REFERENCES organizations (id),
  subscription_id  uuid NOT NULL REFERENCES subscriptions (id),
  entitlement_key  text NOT NULL REFERENCES entitlement_definitions (key),
  int_value        bigint CHECK (int_value >= 0),
  bool_value       boolean,
  unlimited        boolean NOT NULL DEFAULT false,
  reason           text NOT NULL,
  expires_at       timestamptz,
  created_by       uuid,
  created_at       timestamptz NOT NULL DEFAULT now(),
  CHECK ( (CASE WHEN int_value IS NOT NULL THEN 1 ELSE 0 END
         + CASE WHEN bool_value IS NOT NULL THEN 1 ELSE 0 END
         + CASE WHEN unlimited THEN 1 ELSE 0 END) = 1 )
);

-- Counters double as the serialization point for count-type limits (see entitlements.py).
CREATE TABLE usage_counters (
  id               uuid PRIMARY KEY,
  organization_id  uuid NOT NULL REFERENCES organizations (id),
  metric           text NOT NULL REFERENCES entitlement_definitions (key),
  scope_key        text NOT NULL DEFAULT 'org',      -- 'org' or 'company:<uuid>'
  period_key       text NOT NULL DEFAULT 'all',      -- 'all' or 'YYYY-MM'
  value            bigint NOT NULL DEFAULT 0 CHECK (value >= 0),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, metric, scope_key, period_key)
);

CREATE TABLE usage_records (
  id               uuid NOT NULL,
  occurred_at      timestamptz NOT NULL DEFAULT now(),
  organization_id  uuid NOT NULL,
  company_id       uuid,
  metric           text NOT NULL,
  quantity         bigint NOT NULL,
  source_ref       text,
  PRIMARY KEY (id, occurred_at)
) PARTITION BY RANGE (occurred_at);
CREATE TABLE usage_records_default PARTITION OF usage_records DEFAULT;
CREATE INDEX usage_records_org ON usage_records (organization_id, metric, occurred_at);

CREATE TABLE support_access_grants (
  id                 uuid PRIMARY KEY,
  platform_admin_id  uuid NOT NULL REFERENCES platform_admins (id),
  organization_id    uuid NOT NULL REFERENCES organizations (id),
  company_id         uuid,
  access_level       text NOT NULL CHECK (access_level IN ('metadata', 'read')),
  reason             text NOT NULL,
  approved_by        uuid REFERENCES users (id),
  starts_at          timestamptz,
  expires_at         timestamptz,
  status             text NOT NULL DEFAULT 'requested'
                       CHECK (status IN ('requested', 'active', 'revoked', 'expired', 'denied')),
  revoked_at         timestamptz,
  created_at         timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (organization_id, company_id) REFERENCES companies (organization_id, id)
);

-- Retention policy *schema* only (decision D-8): values are deliberately undefined (NULL) until
-- legal counsel supplies them.
CREATE TABLE retention_policies (
  id                    uuid PRIMARY KEY,
  organization_id       uuid REFERENCES organizations (id),   -- NULL = platform default
  entity_kind           text NOT NULL,
  min_retention_months  integer CHECK (min_retention_months >= 0),
  on_expiry             text NOT NULL DEFAULT 'review' CHECK (on_expiry IN ('review', 'archive')),
  created_at            timestamptz NOT NULL DEFAULT now(),
  UNIQUE NULLS NOT DISTINCT (organization_id, entity_kind)
);

-- ---------------------------------------------------------------- operations
CREATE TABLE audit_events (
  id               uuid NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  organization_id  uuid,                    -- NULL only for pre-tenant security events
  company_id       uuid,
  actor_type       text NOT NULL CHECK (actor_type IN ('user', 'system', 'ai', 'platform_admin')),
  actor_id         uuid,
  action           text NOT NULL,
  entity_type      text,
  entity_id        text,
  summary          jsonb NOT NULL DEFAULT '{}'::jsonb,
  ip               inet,
  user_agent       text,
  correlation_id   text,
  support_grant_id uuid,
  PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);
CREATE TABLE audit_events_default PARTITION OF audit_events DEFAULT;
CREATE INDEX audit_events_org_time ON audit_events (organization_id, created_at DESC);

CREATE TABLE outbox_events (
  id               uuid PRIMARY KEY,
  organization_id  uuid,
  company_id       uuid,
  event_type       text NOT NULL,
  payload          jsonb NOT NULL DEFAULT '{}'::jsonb,
  state            text NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'dispatched', 'failed')),
  attempts         integer NOT NULL DEFAULT 0,
  available_at     timestamptz NOT NULL DEFAULT now(),
  created_at       timestamptz NOT NULL DEFAULT now(),
  dispatched_at    timestamptz
);
CREATE INDEX outbox_pending ON outbox_events (available_at) WHERE state = 'pending';

CREATE TABLE idempotency_keys (
  id               uuid PRIMARY KEY,
  user_id          uuid NOT NULL REFERENCES users (id),
  key              text NOT NULL CHECK (length(key) BETWEEN 8 AND 128),
  request_hash     bytea NOT NULL,
  response_status  integer,
  response_body    jsonb,
  created_at       timestamptz NOT NULL DEFAULT now(),
  expires_at       timestamptz NOT NULL,
  UNIQUE (user_id, key)
);
